import{_ as t,a as o,o as a,a6 as s}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Roles","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/roles/index.md","filePath":"api/graphql-api/admin/settings/roles/index.md","lastUpdated":1787290888000}'),d={name:"api/graphql-api/admin/settings/roles/index.md"};function r(i,e,n,l,c,h){return a(),o("div",null,e[0]||(e[0]=[s('<h1 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h1><p>The Roles menu manages the named permission sets that govern what each admin user can do. It mirrors the admin <strong>Settings → Users → Roles</strong> screen.</p><h2 id="what-a-role-is" tabindex="-1">What a role is <a class="header-anchor" href="#what-a-role-is" aria-label="Permalink to &quot;What a role is&quot;">​</a></h2><p>A <strong>role</strong> is a named bundle of permissions assigned to admin users. It controls which areas of the admin panel a user can reach and which actions they can take there. Every admin user is assigned exactly one role; that role is the single source of truth for their access. Roles are referenced when you create or edit an admin user — the user inherits whatever the role grants.</p><h2 id="field-meanings" tabindex="-1">Field meanings <a class="header-anchor" href="#field-meanings" aria-label="Permalink to &quot;Field meanings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code> / <code>_id</code></td><td>The role&#39;s IRI id and numeric id.</td></tr><tr><td><code>name</code></td><td>Display name of the role (e.g. <em>Administrator</em>, <em>Sales</em>).</td></tr><tr><td><code>description</code></td><td>Free-text note describing the role&#39;s purpose.</td></tr><tr><td><code>permissionType</code></td><td><code>all</code> or <code>custom</code> — see below.</td></tr><tr><td><code>permissions</code></td><td>The granted permission keys (see below).</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>Timestamps. The seeded Administrator role has <code>null</code> timestamps.</td></tr></tbody></table><h3 id="permissiontype-—-all-vs-custom" tabindex="-1"><code>permissionType</code> — <code>all</code> vs <code>custom</code> <a class="header-anchor" href="#permissiontype-—-all-vs-custom" aria-label="Permalink to &quot;`permissionType` — `all` vs `custom`&quot;">​</a></h3><ul><li><strong><code>all</code></strong> — the role has <strong>full access</strong> to every area of the admin. No explicit key list is stored, so <code>permissions</code> is <code>null</code> (and is forced to <code>[]</code> whenever you switch an existing role to <code>all</code>).</li><li><strong><code>custom</code></strong> — the role grants only the permission keys listed in <code>permissions</code>. Anything not in the list is denied.</li></ul><h3 id="permissions-—-the-key-list" tabindex="-1"><code>permissions</code> — the key list <a class="header-anchor" href="#permissions-—-the-key-list" aria-label="Permalink to &quot;`permissions` — the key list&quot;">​</a></h3><p>For a <code>custom</code> role this is a <strong>string array</strong> of permission keys. Keys are hierarchical and dotted — a menu key (<code>catalog</code>), a sub-menu key (<code>catalog.products</code>), and per-action keys under it (<code>catalog.products.create</code>, <code>catalog.products.edit</code>, <code>catalog.products.delete</code>, <code>catalog.products.view</code>). To grant an action you typically include its key together with its parent menu/sub-menu keys. A <code>custom</code> role can hold well over a hundred keys.</p><h2 id="create-update-delete" tabindex="-1">Create, update &amp; delete <a class="header-anchor" href="#create-update-delete" aria-label="Permalink to &quot;Create, update &amp; delete&quot;">​</a></h2><ul><li><strong>Create</strong> — supply <code>name</code>, <code>description</code>, and <code>permissionType</code>. For <code>custom</code>, also supply the <code>permissions</code> array; for <code>all</code>, omit it.</li><li><strong>Update</strong> — change any field. <strong>Switching <code>permissionType</code> to <code>all</code> clears <code>permissions</code> to <code>[]</code></strong> (full access has no explicit list). For <code>custom</code>, send the full <code>permissions</code> array you want — it replaces the previous list.</li><li><strong>Delete</strong> — removes the role, subject to the guards below.</li></ul><h2 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h2><p>Deletion is refused when:</p><ul><li>The role is <strong>assigned to one or more admins</strong> — you can&#39;t delete a role still in use; reassign those admins to another role first.</li><li>It is the <strong>last remaining role</strong> — you can&#39;t delete the last role; at least one must always exist.</li></ul><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/settings/roles/list.html">List roles</a></td><td><code>adminSettingsRoles</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/settings/roles/detail.html">Get a single role</a></td><td><code>adminSettingsRole(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/settings/roles/create.html">Create a role</a></td><td><code>createAdminSettingsRole</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/settings/roles/update.html">Update a role</a></td><td><code>updateAdminSettingsRole</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/settings/roles/delete.html">Delete a role</a></td><td><code>deleteAdminSettingsRole</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.roles.create</code> / <code>.edit</code> / <code>.delete</code>.</p>',18)]))}const u=t(d,[["render",r]]);export{p as __pageData,u as default};
